function checkPasswordStrength(p){if(typeof p!=='string'||!p)return{ok:false,level:0,msg:''};if(p.length<8)return{ok:false,level:1,msg:'密钥至少 8 位'};if(p.length>64)return{ok:false,level:2,msg:'密钥不能超过 64 位'};var hasLower=/[a-z]/.test(p),hasUpper=/[A-Z]/.test(p),hasDigit=/\d/.test(p),hasSpecial=/[^a-zA-Z0-9]/.test(p);if(!(hasLower||hasUpper))return{ok:false,level:1,msg:'密钥必须包含字母'};if(!hasDigit)return{ok:false,level:2,msg:'密钥必须包含数字'};var weak=['12345678','password','qwerty123','abc12345','11111111','123456789','password1','admin123'];if(weak.indexOf(p.toLowerCase())>=0)return{ok:false,level:2,msg:'密钥过于常见，请更换'};var level=2;if(p.length>=12)level=3;if(p.length>=12&&hasSpecial&&hasLower&&hasUpper)level=4;else if(p.length>=10&&hasSpecial)level=3;return{ok:true,level:level,msg:''};}
