var loadUsers=function(){try{var r=localStorage.getItem(KEYS.users);return r?JSON.parse(r):{};}catch(e){return{};}};
var saveUsers=function(users){try{localStorage.setItem(KEYS.users,JSON.stringify(users));return true;}catch(e){return false;}};
