function calcHours(day){if(!day.work.enabled)return 0;var w=day.work;var total=durationHours(w.start,w.end);var unpaid=0;(w.breaks||[]).forEach(function(b){unpaid+=durationHours(b.start,b.end);});return Math.max(0,Math.round((total-unpaid)*100)/100);}
function calcPay(day){if(!day.work.enabled)return 0;var h=calcHours(day);var w=day.work.wage||{};var base;if(w.mode==='base'){var md=Number(w.monthDays)||21.75;var sh=Number(w.stdHours)||8;base=h*((Number(w.baseSalary)||0)/md/sh);}else{base=h*(Number(w.hourlyRate)||0);}var allow=(w.allowances||[]).reduce(function(s,a){return s+(Number(a.amount)||0);},0);return Math.round((base+allow)*100)/100;}
